import openai

class AIAgent:
    def __init__(self, model_name="gpt-4"):
        self.model = model_name
        self.client = openai.OpenAI()

    def process_task(self, task, context=""):
        response = self.client.chat.completions.create(
            model=self.model,
            messages=[
                {"role": "system", "content": "You are a helpful AI assistant."},
                {"role": "user", "content": f"{context}\n\n{task}"}
            ]
        )
        return response.choices[0].message.content

    def search_and_answer(self, query):
        # This would integrate with a search API in a real implementation
        search_result = f"Search results for: {query}"
        return self.process_task(f"Based on this information: {search_result}", f"Answer this question: {query}")

